# Own-wording magic items of Valda's Spire of Secrets (2014 rules), Gloves of Skill to Polymorph Potion, plus the plain ammunition rows.
ITEMS = []; SP = {}; WPN = {}; GEAR = []
def add(name, typ, rar, att, text, **o):
    ITEMS.append((name, typ, rar, att, text, o))

add("Gloves of Skill", "Wondrous Item", "Uncommon", 1, "While attuned you are proficient with one tool or instrument. The GM picks it or rolls a d10: drum, flute, horn, lute, lyre, carpenter's tools, cobbler's tools, jeweler's tools, mason's tools, smith's tools.")
for _r, _b in (("Uncommon", 1), ("Rare", 2), ("Very Rare", 3)):
    add("Graverobber's Spade (%s)" % _r.replace("Very Rare", "Very rare"), "Weapon", _r, 1, "A Shovel that serves as a spellcasting focus for your Necromancer spells. You gain +%d to attack and damage rolls with it and the same bonus to spell attack rolls and save DCs of your Necromancer spells. You can cast exhume at will, with no spell slot or material components." % _b, fx={"atk": _b, "dmg": _b, "spellAtk": _b}, base=["Shovel"], by="Necromancer")
add("Hand of Glory", "Wondrous Item", "Very Rare", 1, "A mummified hand worn on a leather cord around the neck. While attuned you gain two extra attunement slots for magic rings, which are worn on its fingers. If your attunement to the hand ends, so does your attunement to the rings on it.")
add("Invisible Ink", "Wondrous Item", "Uncommon", 0, "Writing in this ink is invisible. A DC 25 Intelligence (Investigation) check shows that writing exists but not what it says. Only creatures with truesight or under see invisibility can read it. Dispel magic removes the effect. One pot covers 250 words or one picture or diagram.")
add("Jax", "Potion", "Uncommon", 0, "A vial of brackish orange liquid that you inject as an action. For 1 hour your Strength, Dexterity and Constitution each rise by 4, and their maximum becomes 24. Your hit point maximum drops permanently by 1d12 each dose, and only greater restoration or wish restores it. You can take several doses and the increases stack. Each extra dose requires a DC 20 Constitution save or you overdose: you drop to 0 hit points and cannot regain any for 1 hour.")
add("Lady and Lord Rings", "Ring", "Very Rare", 1, "A matched pair, one showing a lord and one a lady. Two creatures attune, one ring each. While within 30 ft of each other both have resistance to all damage, and each time one takes damage the other loses the same number of hit points. Attunement breaks if either creature drops to 0 hit points or ends attunement.", by="Two creatures")
add("Leaden Manacles", "Wondrous Item", "Uncommon", 0, "Manacles that work as normal manacles, with one addition. A creature wearing them that tries to cast a spell makes a DC 12 ability check with its spellcasting ability. On a failure the spell fails, the slot and action are spent, and the caster takes 1d6 Fire per level of the slot. On a success the caster takes half that damage and the spell works.")
add("Leonora's Throne of Indolence", "Wondrous Item", "Very Rare", 1, "A 100-lb oak and gold armchair. Sit in it and speak its command word as an action: it hovers with a flying speed of 50 ft and carries up to 400 lb until you say the word again. A second command word casts unseen servant through it, and the servant can also conjure a spectral trumpet to announce you. A third word creates up to 10 lb of fine food and up to four bottles of wine that only you can enjoy (it turns stale and foul for others). That one works once per dawn.", ch=[1, "1", "dawn"])
SP["Leonora's Throne of Indolence"] = {"sp": [["Unseen Servant", 1]]}
add("Locket of Remembrance", "Wondrous Item", "Common", 0, "Made with the name and likeness of a dead creature engraved, and dedicated to it. While a living creature wears the locket, the remembered creature's remains cannot become undead and its soul cannot linger as an undead.")
add("Loincloth of Oni Magic", "Wondrous Item", "Very Rare", 1, "A blood-red loincloth. You can cast and concentrate on spells you know even while raging. It has 6 charges and regains 1d6 at dusk. As an action spend charges to cast (save DC 17): charm person 1, sleep 1, darkness 2, invisibility 2, gaseous form 3, cone of cold 4.", by="Barbarian", ch=[6, "1d6", "dusk"])
SP["Loincloth of Oni Magic"] = {"sp": [["Charm Person", 1], ["Sleep", 1], ["Darkness", 2], ["Invisibility", 2], ["Gaseous Form", 3], ["Cone of Cold", 4]]}
add("Marvelous Painted World", "Wondrous Item", "Legendary", 0, "A masterwork painting at least 5 ft square, made with at least ten pots of marvelous pigments. It is a portal to a demiplane holding the painted world, wide enough for Medium creatures. Inside, a misty archway leads back to the real world. If the painting is rolled up or faced to a solid surface, the portal vanishes inside. The painter decides what the place holds. Its objects and creatures cannot leave and turn to smoke if taken out by other means. Time passes at half speed there and you need no food or drink.")
add("Memento Mori", "Wondrous Item", "Rare", 0, "A sealed chronomancy letter describing how the reader will die, in specific or cryptic words and never with an exact time. After reading, the creature has Advantage on death saving throws and dies only on five failures instead of three. At the moment of death the letter describes, it dies without making death saves. The effect ends only if the character dies and is revived. Once read, the letter loses its magic.")
add("Morbid Makeup", "Wondrous Item", "Uncommon", 0, "A kit of red, white and black paint that works as a disguise kit and lets you pass as a fey, fiend or undead creature. While made up, you have Advantage on Charisma (Intimidation) checks against humanoids. It holds 10 applications. Each lasts up to 8 hours or until washed off as an action.")
add("Mouse of Cowardice", "Wondrous Item", "Rare", 0, "A wind-up clockwork mouse that frightens even huge beasts. Speak its command word and set it rolling at a Large or larger creature within 15 ft as an action to cast phantasmal killer through it (save DC 15). It cannot be used again until the next dawn.", ch=[1, "1", "dawn"])
SP["Mouse of Cowardice"] = {"sp": [["Phantasmal Killer", 4]]}
add("Necromantic Draught", "Potion", "Rare", 0, "A glowing neon-yellow goo that recoils from living things touching its container. Poured on a Small or Medium humanoid corpse, it casts animate dead for 24 hours. You command undead raised this way.")
add("Ooze Bottle", "Potion", "Rare", 0, "A vial of lurching charcoal liquid. As an action, throw it up to 20 ft. It shatters and releases a gray ooze that is friendly to you and your allies and attacks the nearest creature it senses, or follows you if none. After 1 hour it collapses into lifeless sludge.")
add("Parchment of Sending", "Wondrous Item", "Uncommon", 0, "Holds a message of 25 words or fewer, and extra text is erased. Address it to a creature you know and it folds into a glider and seeks that creature within 24 hours if it is on your plane. The recipient can add 25 words and address it to you to send it back. After four trips it becomes plain parchment.")
for _r, _b in (("Uncommon", 1), ("Rare", 2), ("Very Rare", 3)):
    add("Pentacle of Woe (%s)" % _r.lower(), "Wondrous Item", _r, 1, "A medallion that gives +%d to spell attack rolls and the save DCs of your Witch hexes and spells. It has 3 charges and regains all at dusk. Spend a charge to cast a hex that normally takes an action as a Bonus Action instead." % _b, by="Witch", ch=[3, "all", "dusk"])
add("Phase Arrow", "Weapon", "Uncommon", 0, "An ethereal arrow that passes through everything but its target. You ignore all cover, including full cover, when attacking with it. It can target creatures on the Ethereal Plane as if they were on the Material Plane, and the reverse. Once it hits, it is no longer magical.", base=["Arrow"])
add("Polymorph Potion", "Potion", "Rare", 0, "A purple liquid from mimic blood. For 1 hour you gain the effect of polymorph, and roll a d20 for your form: rat, rabbit, cat, octopus, weasel, goat, owl, draft horse, eagle, mastiff, constrictor snake, wolf, ape, crocodile, giant toad, commoner (random look), brown bear, tiger, elephant, tyrannosaurus rex.")
add("Portable Cannonballs", "Wondrous Item", "Uncommon", 0, "A bag of twenty 1-inch iron balls of 1/4 lb each. As a Bonus Action with the command word, any number of them grow into 10-lb cannonballs. Poured out as an action, the bag works as ball bearings, and the word then expands every ball at once. A rolling mass of expanded balls forces creatures in its path to make a DC 13 Dexterity save or take 2d10 Bludgeoning. A single ball can be fired from a sling or firearm and expanded in flight, dealing 2d12 Bludgeoning on a hit, but those attacks have Disadvantage.")

GEAR += [
 ["Atlatl Javelin", 0.5, 2, "Ammunition", "Ammunition thrown with an atlatl."],
 ["Ballista Bolt", 1, 2, "Ammunition", "Ammunition for a Portable Ballista."],
 ["Blunderbuss shot (10)", 1, 2, "Ammunition", "Ten loads of scatter shot for a Blunderbuss."],
 ["Bullets (10)", 2, 2, "Ammunition", "Ten firearm bullets."],
 ["Cannonball", 5, 10, "Ammunition", "A single iron ball for a Light Cannon."],
 ["Dragon Bullet", 1, 0, "Ammunition", "A single bullet for a Dragon Rifle."],
 ["Greatbow Arrow (5)", 1, 10, "Ammunition", "Five heavy arrows for a Greatbow."],
 ["Grenade", 3, 3, "Ammunition", "A single explosive round for a Grenade Launcher."],
 ["Musket balls (10)", 1, 2, "Ammunition", "Ten balls for a Musket or other muzzle-loader."],
 ["Rocket", 20, 6, "Ammunition", "A single rocket for a Rocket Launcher."],
 ["Shell (10)", 5, 2, "Ammunition", "Ten shotgun shells."],
]
